// Shared agent picker for the studio and the Zenith presentation.
window.addEventListener('DOMContentLoaded',()=>{'use strict';
for(const panel of document.querySelectorAll('.agent-panel'))mount(panel);
function mount(panel){
const id=name=>panel.dataset.agentPrefix?panel.dataset.agentPrefix+'-'+name:name;
const el=name=>panel.querySelector('#'+id(name)),form=el('agent-form');if(!form)return;
const target=form.closest('[data-agent-target]')?.dataset.agentTarget||'scene';
const content=target==='typescript'?'TypeScript component':target;
const auth=window.GLYPH_BRIDGE,prompt=el('agent-prompt'),send=el('agent-send'),stop=el('agent-stop'),undo=el('agent-undo'),status=el('agent-status'),response=el('agent-result'),model=el('agent-model'),picker=el('agent-provider'),privacy=el('agent-privacy');
let voiceBusy=false;
let busy=false,polling=false,latest=null,localMessage='',profileKey='';try{const saved=localStorage.getItem('glyph-agent-provider');if(['hermes','codex'].includes(saved))picker.value=saved;}catch{}
async function api(route,body){const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error?.message||'Agent connection failed');return d;}
function render(d){latest=d;busy=d.job?.status==='running';const job=(d.job?.target||'scene')===target?d.job:null;const list=d.providers||[{id:'hermes',connected:d.connected,modelLabel:d.modelLabel}];for(const option of picker.options){const p=list.find(p=>p.id===option.value);option.disabled=!p?.connected;}
 const p=list.find(p=>p.id===picker.value);send.disabled=!p?.connected||busy||voiceBusy;picker.disabled=busy;stop.hidden=!busy;undo.disabled=!d.canUndo||busy;
 model.textContent=p?.connected?(picker.value==='codex'?'CODEX / ':'ON-DEVICE / ')+(p.modelLabel||'Connected'):'OFFLINE';privacy.textContent=picker.value==='codex'?'Codex receives your prompt and current '+content+' through your signed-in Codex account.':'Local Hermes uses your on-device model. Your prompt and '+content+' stay on this computer.';
 const profile=d.designer,key=profile?JSON.stringify([profile,picker.value]):'';if(key!==profileKey){profileKey=key;el('designer-info').hidden=!profile;if(profile){el('designer-role').textContent=profile.role+' · '+profile.purpose;el('designer-skills').replaceChildren(...profile.skills.map(skill=>{const li=document.createElement('li');const strong=document.createElement('strong');strong.textContent=skill.name;li.append(strong,document.createTextNode(' — '+skill.description));return li;}));el('designer-tools').textContent=target==='typescript'?'TypeScript proposal · type checked · isolated worker preview.':target==='program'?'Source proposal · syntax checked · isolated worker preview.':(profile.tools[picker.value]||[]).filter(n=>n.startsWith('glyph_flow_')===(target==='flow')).length+(picker.value==='codex'?' read-only tools · validated proposals.':' scoped tools · revision-checked edits.');el('designer-memory').textContent=profile.memory;}}
 const stages={glyph_flow_read:'Reading flow…',glyph_flow_validate:'Validating flow…',glyph_flow_edit:'Editing draft…',glyph_flow_apply:'Staging flow…',glyph_flow_invoke:'Queuing method call…',glyph_studio_library:'Reading design library…',glyph_studio_audit:'Auditing scene…',glyph_studio_read:'Reading scene…',glyph_studio_update:'Updating layer…',glyph_studio_apply:'Applying scene…',glyph_studio_compile:'Checking recipe…',glyph_studio_add:'Adding layer…',glyph_studio_remove:'Removing layer…',glyph_studio_preview:'Checking playback…'};
 status.textContent=busy?((d.job.provider==='codex'?'Codex · ':'Hermes · ')+(stages[d.job.stage]||d.job.stage)):job?.status==='complete'?'Complete':job?.status==='undone'?'Undone':job?.status==='failed'?'Needs attention':job?.status==='cancelled'?'Stopped':p?.connected?'Ready':'Connect the selected agent';
 response.textContent=localMessage||job?.message||'';
}
async function poll(){if(polling||!auth)return;polling=true;try{render(await api('agent?provider='+picker.value+'&target='+target));}catch(e){send.disabled=true;status.textContent='Disconnected';localMessage=e.message;response.textContent=e.message;}finally{polling=false;}}
picker.onchange=()=>{localMessage='';try{localStorage.setItem('glyph-agent-provider',picker.value);}catch{}if(latest)render(latest);poll();};
form.onsubmit=async e=>{e.preventDefault();if(busy||voiceBusy||!auth)return;send.disabled=true;localMessage='';response.textContent='';try{
 let context={};if(target==='typescript'){await window.glyphTypeScriptStudio?.flush();context.preview_feedback=window.glyphTypeScriptStudio?.feedback();}
 if(target==='program'){await window.glyphProgramStudio?.flush();context.preview_feedback=window.glyphProgramStudio?.feedback();}
 if(target==='flow')await window.glyphFlowStudio?.flush();
 if(target==='scene'&&window.glyphStudio){if(window.glyphStudio.hasUnbuiltChanges())throw Error('Build your directive or inspector changes before prompting the agent.');await window.glyphBridge?.publish(window.glyphStudio.getScene());const saved=await api('state');if(JSON.stringify(saved.scene)!==JSON.stringify(window.glyphStudio.getScene()))throw Error('The built scene is still syncing. Resolve any scene conflict, then try again.');}
 render(await api('agent',{prompt:prompt.value,provider:picker.value,target,...context}));
 }catch(e){localMessage=e.message;response.textContent=e.message;send.disabled=false;}};
stop.onclick=async()=>{try{render(await api('agent/cancel',{}));}catch(e){localMessage=e.message;response.textContent=e.message;}};
undo.onclick=async()=>{undo.disabled=true;try{await api('agent/undo',{target});await poll();}catch(e){localMessage=e.message;response.textContent=e.message;}};
prompt.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();form.requestSubmit();}};
const mic=document.createElement('button'),voiceNote=document.createElement('p'),discard=document.createElement('button');mic.type=discard.type='button';mic.id=id('agent-dictate');mic.textContent='Dictate ◉';mic.disabled=true;mic.setAttribute('aria-pressed','false');discard.textContent='Discard recording';discard.hidden=true;voiceNote.id=id('agent-voice-status');voiceNote.setAttribute('role','status');voiceNote.setAttribute('aria-live','polite');form.querySelector('.agent-actions').append(mic,discard);form.append(voiceNote);
let recorder=null,stream=null,recordTimer=null,recordParts=[],discarded=false,seconds=0,voiceReady=false;
function voiceState(value){voiceBusy=value;mic.setAttribute('aria-pressed',String(!!recorder&&recorder.state==='recording'));if(latest)render(latest);}
function releaseMic(){clearInterval(recordTimer);recordTimer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;}
function stopRecording(cancel=false){discarded=cancel;if(recorder?.state==='recording')recorder.stop();releaseMic();discard.hidden=true;mic.textContent='Transcribing…';mic.disabled=true;}
mic.onclick=async()=>{if(recorder?.state==='recording'){stopRecording();return;}if(!voiceReady||voiceBusy)return;voiceState(true);mic.disabled=true;voiceNote.textContent='Requesting microphone access…';try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,type?{mimeType:type}:{});recordParts=[];discarded=false;seconds=0;recorder.ondataavailable=e=>{if(e.data.size)recordParts.push(e.data);};recorder.onerror=()=>{discarded=true;stopRecording(true);voiceNote.textContent='Recording failed. Check microphone access, then try again.';};recorder.onstop=async()=>{releaseMic();discard.hidden=true;try{if(discarded){voiceNote.textContent='Recording discarded.';return;}voiceNote.textContent='Transcribing on this computer…';const audio=new Blob(recordParts,{type:recorder.mimeType||type||'audio/webm'});if(audio.size>10000000)throw Error('Recording is too large. Try a shorter one.');const r=await fetch('/api/voice',{method:'POST',headers:{Authorization:'Bearer '+auth.token,'Content-Type':audio.type},body:audio}),data=await r.json();if(!r.ok)throw Error(data.error?.message||'Local transcription failed.');const text=data.text.trim();if(!text){voiceNote.textContent='No speech detected. Try again.';return;}const separator=prompt.value&&!/\s$/.test(prompt.value)?' ':'';if(prompt.value.length+separator.length+text.length>6000){voiceNote.textContent='Transcript exceeds the prompt limit. Copy the text below into a shorter prompt: '+text;return;}prompt.value+=separator+text;prompt.dispatchEvent(new Event('input',{bubbles:true}));prompt.focus();voiceNote.textContent='Transcript added. Review it, then send your prompt.';}catch(e){voiceNote.textContent=e.message;}finally{recordParts=[];recorder=null;voiceState(false);mic.disabled=false;mic.textContent='Dictate ◉';}};recorder.start();mic.disabled=false;mic.textContent='Finish dictation ■';discard.hidden=false;voiceState(true);voiceNote.textContent='Listening · 0 / 60s · on-device transcription';recordTimer=setInterval(()=>{seconds++;voiceNote.textContent='Listening · '+seconds+' / 60s · on-device transcription';if(seconds>=59)stopRecording();},1000);}catch(e){releaseMic();voiceState(false);mic.disabled=false;voiceNote.textContent=e.name==='NotAllowedError'?'Microphone permission was denied. Allow access in your browser to dictate.':'Microphone unavailable. You can still type, paste or use system dictation.';}};
discard.onclick=()=>stopRecording(true);window.addEventListener('pagehide',()=>{discarded=true;stopRecording(true);});
if(auth&&navigator.mediaDevices?.getUserMedia&&window.MediaRecorder){api('voice').then(d=>{voiceReady=d.available;mic.disabled=!voiceReady;voiceNote.textContent=d.available?'Dictation stays on this computer. Recording starts only when you click Dictate.':'Connect a local Whisper runtime with npm run connect:voice to enable dictation.';}).catch(()=>{voiceNote.textContent='Local dictation is unavailable. You can still use system dictation in this field.';});}else voiceNote.textContent='Use system dictation in this field, or open the dev server in a browser with microphone support.';
if(auth){poll();setInterval(()=>{if(!document.hidden)poll();},700);}else{send.disabled=true;picker.disabled=true;model.textContent='STANDALONE';status.textContent='Open the local studio to connect';privacy.textContent='Run the dev server and open http://127.0.0.1:8788/ to use Hermes or Codex.';}
}
});
